<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#45166f"><title>Jorsid Beauty · Administration</title><link rel="icon" href="{{ asset('images/favicon.png') }}"><style>*{box-sizing:border-box}body{margin:0;min-height:100vh;display:grid;place-items:center;padding:20px;background:radial-gradient(circle at 10% 15%,#e7d6ff,transparent 36%),radial-gradient(circle at 90% 90%,#fbd5f0,transparent 34%),linear-gradient(135deg,#f9f5ff,#eef7ff);font:15px/1.5 system-ui,sans-serif;color:#2b1644}.box{width:min(470px,94vw);background:#ffffffeb;backdrop-filter:blur(14px);padding:34px;border:1px solid #fff;border-radius:26px;box-shadow:0 24px 80px #45166f1a}.brand{display:flex;align-items:center;gap:14px;margin-bottom:24px}.brand img{width:64px;height:64px;object-fit:contain;background:#fff;border-radius:18px;box-shadow:0 8px 25px #5a1d7e15}.brand h1{font-size:23px;line-height:1.15;margin:0;color:#481568}.brand small{color:#8d4aab}.lang{display:flex;justify-content:flex-end;margin-bottom:12px}.lang select{border:1px solid #e4d4ef;border-radius:10px;background:#fff;padding:8px;color:#51206e}p{color:#79678b}label{display:block;font-size:12px;font-weight:750;margin:13px 0 5px}input{width:100%;padding:13px;border:1px solid #e1d1ed;border-radius:12px;box-sizing:border-box;margin:0 0 8px;font:inherit}input:focus{outline:none;border-color:#a03fc2;box-shadow:0 0 0 4px #9b2fc419}button{background:linear-gradient(100deg,#7118c8,#df0c99);color:white;border:0;border-radius:12px;padding:13px 16px;width:100%;font-weight:800;cursor:pointer;box-shadow:0 8px 22px #b016b329;margin-top:12px}a{color:#8022a0}.err{color:#a20d47;background:#fff0f4;border-radius:10px;padding:10px}.back{text-align:center;margin:20px 0 0;font-size:13px}.tiny{text-align:center;font-size:11px;color:#a18da9;margin-top:20px}</style></head><body><form class="box" method="post" action="{{ route('admin.login.submit') }}">@csrf<div class="lang"><select id="login-language" aria-label="Langue"><option value="de">🇩🇪 Deutsch</option><option value="fr">🇫🇷 Français</option><option value="en">🇬🇧 English</option></select></div><div class="brand"><img src="{{ asset('images/jorsid-logo.jpg') }}" alt="Jorsid Beauty"><div><h1>Jorsid Beauty</h1><small>by Kessy</small></div></div><h2 data-i18n="title">Connexion administration</h2><p data-i18n="intro">Connexion sécurisée à l’administration.</p>@if($errors->any())<p class="err">{{ $errors->first() }}</p>@endif<label for="email" data-i18n="email">E-mail administrateur</label><input id="email" type="email" name="email" value="{{ old('email') }}" autocomplete="username" required autofocus placeholder="admin@exemple.com"><label for="password" data-i18n="password">Mot de passe</label><input id="password" type="password" name="password" autocomplete="current-password" required placeholder="••••••••"><button data-i18n="submit">Se connecter</button><p class="back"><a href="{{ route('home') }}" data-i18n="back">← Retour au site</a></p><div class="tiny">© {{ date('Y') }} Jorsid Beauty by Kessy</div></form><script>(()=>{const T={title:['Administrator login','Connexion administration','Admin login'],intro:['Sicherer Zugang zur Administration.','Connexion sécurisée à l’administration.','Secure sign-in to the admin area.'],email:['Administrator-E-Mail','E-mail administrateur','Administrator email'],password:['Passwort','Mot de passe','Password'],submit:['Anmelden','Se connecter','Sign in'],back:['← Zur Website','← Retour au site','← Back to website']};const select=document.getElementById('login-language');let lang='de';try{lang=localStorage.getItem('jorsid-language')||'de'}catch(e){}if(!['de','fr','en'].includes(lang))lang='de';select.value=lang;function apply(l){const i={de:0,fr:1,en:2}[l];document.documentElement.lang=l;document.querySelectorAll('[data-i18n]').forEach(el=>el.textContent=T[el.dataset.i18n][i]);document.querySelector('#email').placeholder=l==='de'?'admin@beispiel.de':l==='en'?'admin@example.com':'admin@exemple.com';try{localStorage.setItem('jorsid-language',l)}catch(e){}}select.addEventListener('change',()=>apply(select.value));apply(lang)})();</script></body></html>